(function() {
  'use strict';
  // Hue-shift the entire interface based on cursor angle for kinetic color play
  const root = document.documentElement;
  function updateHue(event) {
    const x = event.clientX / window.innerWidth - 0.5;
    const y = event.clientY / window.innerHeight - 0.5;
    const angle = Math.atan2(y, x);
    const hue = Math.round((angle / (Math.PI * 2) + 0.5) * 360);
    root.style.setProperty('--lc-hue', hue + 'deg');
  }
  window.addEventListener('pointermove', updateHue);
})();

