:root {
  /* Liquid Crystal Theme - iridescent microtextures and kinetic hue shifting */
  --bg-primary: #05060c;
  --bg-alt: #0a0f1c;
  --text-primary: #f0f7ff;
  --text-secondary: #b9c7ff;
  --accent: #7cf2ff;
  --accent-2: #9eff8f;
  --border: rgba(124, 242, 255, 0.35);
  --lc-hue: 210deg;
}

body {
  background: linear-gradient(160deg, #05060c 0%, #0a0f1c 55%, #05060c 100%);
  color: var(--text-primary);
}

.card {
  background: radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.05), transparent 40%),
              linear-gradient(120deg, rgba(124, 242, 255, 0.18), rgba(158, 255, 143, 0.14)),
              rgba(10, 15, 28, 0.9);
  border: 1px solid var(--border);
  box-shadow: 0 18px 38px rgba(0, 0, 0, 0.45), 0 0 1px rgba(124, 242, 255, 0.4);
  backdrop-filter: blur(8px) saturate(130%);
  position: relative;
  overflow: hidden;
}

.card::before {
  content: '';
  position: absolute;
  inset: -15%;
  background: conic-gradient(from var(--lc-hue), rgba(124, 242, 255, 0.16), rgba(158, 255, 143, 0.12), rgba(124, 242, 255, 0.16));
  mix-blend-mode: screen;
  filter: blur(32px);
  opacity: 0.65;
  pointer-events: none;
  animation: rippleShift 18s ease-in-out infinite alternate;
}

.card::after {
  content: '';
  position: absolute;
  inset: 6%;
  border-radius: 12px;
  background: radial-gradient(circle at 60% 40%, rgba(255, 255, 255, 0.06), transparent 45%);
  mix-blend-mode: overlay;
  pointer-events: none;
}

.card-title {
  text-transform: uppercase;
  letter-spacing: 0.8px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  -webkit-background-clip: text;
  color: transparent;
}

.button {
  background: linear-gradient(100deg, rgba(124, 242, 255, 0.18), rgba(158, 255, 143, 0.18));
  border: 1px solid rgba(124, 242, 255, 0.55);
  color: var(--text-primary);
  transition: transform 0.2s ease, box-shadow 0.2s, border-color 0.2s;
}

.button:hover {
  transform: translateY(-2px) scale(1.02);
  border-color: rgba(158, 255, 143, 0.7);
  box-shadow: 0 12px 24px rgba(124, 242, 255, 0.25);
}

@keyframes rippleShift {
  0% { transform: scale(1); opacity: 0.6; }
  50% { transform: scale(1.12); opacity: 0.8; }
  100% { transform: scale(0.96); opacity: 0.65; }
}
